+  it("packs whole paragraphs into about 100 to 160 words", () => {
+    const spans = buildWindows([para(1, 60), para(2, 60), para(3, 60), para(4, 60), para(5, 60)]);
+    expect(spans).toEqual([
+      { startN: 1, endN: 2, words: 120 },
+      { startN: 3, endN: 5, words: 180 },
